function validate([n, k]) {
  if (!Number.isInteger(n) || n < 1 || n > 20) return 'n is a whole number from 1 to 20.';
  if (!Number.isInteger(k) || k < 1 || k > 2 ** n - 1) return 'k is a position from 1 to 2^n - 1.';
  return null;
}

