function findKthBit(n, k) {
  if (n === 1) {
    return '0';
  }
  const mid = 2 ** (n - 1);
  if (k === mid) {
    return '1';
  }
  if (k < mid) {
    return findKthBit(n - 1, k);
  }
  const mirrored = findKthBit(n - 1, 2 * mid - k);
  return mirrored === '0' ? '1' : '0';
}

brute:
function findKthBit(n, k) {
  // Build every level as a real string and read the character.
  let current = '0';
  for (let level = 2; level <= n; level++) {
    let tail = '';
    for (let i = current.length - 1; i >= 0; i--) tail += current[i] === '0' ? '1' : '0';
    current = current + '1' + tail;
  }
  return current[k - 1];
}

