function generate(rand, size) {
  const n = size === 'large' ? 15 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 8);
  const length = 2 ** n - 1;
  const roll = rand();
  let k;
  if (roll < 0.1) k = 1;
  else if (roll < 0.2) k = length;
  else if (roll < 0.3) k = 2 ** (n - 1);
  else k = 1 + Math.floor(rand() * length);
  return [n, k];
}
